static void compareSd(const char*label){clearIo();g_msiM12RemapDone=false;Trace old;old.result=before::msiClawPrepareForVirtualStart();old.calls=calls;old.reports=reports;old.cache=g_msiM12RemapDone;clearIo();g_msiM12RemapDone=false;ymcc::msi::rearSdPreparation::Receipt receipt;const bool now=candidate::msiClawPrepareForVirtualStart(&receipt);check(now==old.result,label);check(old.calls==calls,"SD IO order differs");check(old.reports==reports,"SD exact wire bytes differ");check(old.cache==g_msiM12RemapDone,"SD cache differs");check(receipt.returned==now,"SD returned receipt differs");check(receipt.hardwareWriteIssued==!reports.empty(),"SD write issue dishonest");const auto fields=ymcc::msi::rearSdPreparation::fields<json>(receipt);check(!fields["mappingVerified"].get<bool>(),"write receipt became physical mapping proof");if(!reports.empty()){check(fields["capabilityId"]=="controller.configuration.msi.rear.dinput-buttons","SD total catalog receipt missing");check(fields["modelId"].get<std::string>()==ymcc::capabilities::configuration::rearModel(g_machineIdentity.deviceClass,g_machineIdentity.product)->deviceId,"SD exact model receipt missing");}balanced();}
